import json, re, datetime
V = vars

def s(k):
    x = V.get(k)
    if x is None:
        return ''
    x = str(x).strip()
    if x.lower() in ('none', 'null'):
        return ''
    return x

def fnum(k):
    x = s(k)
    if not x:
        return None
    try:
        return float(x.replace(',', '.'))
    except Exception:
        return None

def ival(x, d=0):
    try:
        return int(float(str(x)))
    except Exception:
        return d

def jload(k):
    try:
        x = json.loads(s(k) or '[]')
        return x if isinstance(x, list) else []
    except Exception:
        return []

ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = dict(zip(['1', '2', '3', '4'], ['birinci', 'ikinci', 'üçüncü', 'dördüncü']))
CURN = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
CURSUB = dict(TL='kuruş', USD='sent', EUR='sent', GBP='peni')
HARM = dict(zip(list('aıeiouöü'), list('ııiiuuüü')))

def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    out = []
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (nm == 'bin' and q == 1) else w3(q % 1000) + ' ' + nm)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)

def money(x, c):
    cents = int(round(abs(x) * 100))
    a, k = divmod(cents, 100)
    t = words(a) + ' ' + CURN[c]
    if k:
        t = t + ' ' + words(k) + ' ' + CURSUB[c]
    return t

def cop(t):
    t = t.rstrip()
    lw = t.split()[-1] if t.split() else 'e'
    low = lw.replace('İ', 'i').replace('I', 'ı').lower()
    vs = [ch for ch in low if ch in HARM]
    h = HARM[vs[-1]] if vs else 'i'
    d = 't' if low[-1] in 'çfhkpsşt' else 'd'
    return t + d + h + 'r'

def pdate(x):
    x = str(x or '').strip()
    try:
        m = re.match(r'^(\d{1,2})[./](\d{1,2})[./](\d{4})', x)
        if m:
            return datetime.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
        m = re.match(r'^(\d{4})-(\d{2})-(\d{2})', x)
        if m:
            return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None
    return None

def dtr(d):
    return str(d.day) + ' ' + MONTHS[d.month - 1] + ' ' + str(d.year)

def dcop(d):
    w = words(d.year)
    return dtr(d) + "'" + cop(w)[len(w):]

def dw(x):
    return ' '.join(DIG[int(ch)] for ch in str(x) if ch.isdigit())

def digits(x):
    return re.sub(r'[^0-9]', '', str(x or ''))

def safe_name(n):
    n = str(n or '').strip()
    if not n or n.lower() in ('none', 'null') or len(n) > 40 or len(n.split()) > 5:
        return ''
    low = n.lower()
    for b in ('talimat', 'yok say', 'ignore', 'instruction', 'prompt', 'sistem', 'numara', ' oku', 'kural', 'http'):
        if b in low:
            return ''
    return n

def norm(t):
    t = str(t or '').replace('İ', 'i').replace('I', 'ı').lower()
    for a, b in (('ı', 'i'), ('ğ', 'g'), ('ü', 'u'), ('ş', 's'), ('ö', 'o'), ('ç', 'c'), ('â', 'a')):
        t = t.replace(a, b)
    return re.sub(r'[^a-z0-9 ]', ' ', t)

STOP = set(['yildiz', 'kart', 'karti', 'kartim', 'kartimin', 'kartimi', 'kartimdaki', 'kredi', 'kartinin', 'olan', 'benim', 'borcu', 'borcunu'])

def toks(t):
    return [w for w in norm(t).split() if w not in STOP and len(w) > 1]

try:
    today = datetime.date.fromisoformat(s('now')[:10])
except Exception:
    today = datetime.date(2026, 10, 12)

def load_cards():
    lst = None
    raw = V.get('cards_raw')
    if isinstance(raw, list):
        lst = raw
    elif isinstance(raw, str) and raw.strip().startswith('['):
        try:
            lst = json.loads(raw)
        except Exception:
            try:
                lst = json.loads(raw.replace("'", '"').replace('True', 'true').replace('False', 'false').replace('None', 'null'))
            except Exception:
                lst = None
    if not lst:
        tmp = dict()
        for k in list(V.keys()):
            m = re.search(r'cards(?:\.|\[)(\d+)\]?\.(cardNumber|cardNumberLast4|productName)$', str(k))
            if m:
                tmp.setdefault(int(m.group(1)), dict())[m.group(2)] = V.get(k)
        lst = [tmp[i] for i in sorted(tmp)]
    out = []
    for c in lst or []:
        if not isinstance(c, dict):
            continue
        num = str(c.get('cardNumber') or '').strip()
        l4 = digits(c.get('cardNumberLast4'))[-4:] or digits(num)[-4:]
        if not num and not l4:
            continue
        out.append(dict(num=num or l4, l4=l4, name=safe_name(c.get('productName'))))
    return out

cards = jload('cards_json')

def card_by_num(n):
    for c in cards:
        if c['num'] == n:
            return c
    return None

def cref(c):
    nm = c.get('name') or ''
    return 'Sonu ' + dw(c['l4']) + ' ile biten ' + (nm + ' ' if nm else '') + 'kart'

def tail_match(num, d):
    n = re.sub(r'[^0-9*]', '', str(num))
    if not d or len(d) > len(n):
        return 'no'
    tail = n[-len(d):]
    unknown = False
    for a, b in zip(tail, d):
        if a == '*':
            unknown = True
            continue
        if a != b:
            return 'no'
    return 'maybe' if unknown else 'yes'

def reset_answers():
    V['pick_kind'] = 'none'
    V['pick_name'] = 'none'
    V['card_digits'] = 'none'
    V['extra_request'] = 'none'
    V['yn'] = 'none'
    V['offer_choice'] = 'none'
    V['week_choice'] = 'none'

def ask(node, stage, full, short):
    if stage != s('stage'):
        V['tries'] = 0
    V['stage'] = stage
    V['q_full'] = full
    V['q_say'] = full
    V['q_short'] = short
    V['go'] = node

def retry(full, short):
    t = ival(V.get('tries')) + 1
    V['tries'] = t
    if t >= 3:
        end('end_fail')
        return
    V['q_full'] = full
    V['q_say'] = full
    V['q_short'] = short
    V['go'] = s('go_last') or 'end_fail'

def end(node, line=' '):
    V['go'] = node
    V['done_line'] = line if line.strip() else ' '

def call(node, stage, resets):
    for k in resets:
        V[k] = 'none'
    V['stage'] = stage
    V['go'] = node

def status_bad(node):
    st = s(node + '_status_code')
    return bool(st) and st != '200'

# ---------------------------------------------------------------------------- card selection

def names_text(cl):
    seen = []
    for c in cl:
        t = c['name'] if c['name'] else 'sonu ' + dw(c['l4']) + ' ile biten kartınız'
        if t not in seen:
            seen.append(t)
    if len(seen) == 1:
        return seen[0]
    return ', '.join(seen[:-1]) + ' ve ' + seen[-1]

def select_question(pool, prefix=''):
    names = []
    for c in pool:
        if c['name'] and c['name'] not in names:
            names.append(c['name'])
    if len(pool) > 1 and len(names) == 1 and all(c['name'] == names[0] for c in pool):
        same_name_question(pool, prefix)
        return
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(names) >= 2:
        full = q + ' Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    elif len(names) == 1:
        full = q + ' Örneğin, ' + names[0] + ' diyebilirsiniz.'
    else:
        full = q + ' Kartınızın son dört hanesini söyleyebilirsiniz.'
    ask('ask_card', 'card_q', (prefix + ' ' + full).strip(), q)

def same_name_question(group, prefix=''):
    V['cand_json'] = json.dumps([c['num'] for c in group])
    nm = group[0]['name']
    q = nm + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?'
    ask('ask_digits', 'digits4', (prefix + ' ' + q).strip(), 'Kartınızın son dört hanesini söyler misiniz?')

def pick(c):
    V['sel_card'] = c['num']
    V['sel_l4'] = c['l4']
    V['sel_name'] = c['name'] or ' '
    reset_balance()
    V['stage'] = 'balance'
    V['go'] = 'balance'

def reset_balance():
    keys = ['bal_rc', 'bal_name', 'bal_sd', 'bal_lpd', 'bal_status']
    for cc in ('TL', 'USD', 'EUR', 'GBP'):
        for f in ('sd', 'min', 'rem', 'remmin', 'tot', 'auto', 'st'):
            keys.append('b_' + cc + '_' + f)
    for k in keys:
        V[k] = 'none'

def match_name(said, pool):
    st = toks(said)
    if not st:
        return []
    def has(tok):
        return any(w == tok or w.startswith(tok) for w in st)
    full = [c for c in pool if c['name'] and toks(c['name']) and all(has(t) for t in toks(c['name']))]
    if full:
        mx = max(len(toks(c['name'])) for c in full)
        return [c for c in full if len(toks(c['name'])) == mx]
    part = [c for c in pool if c['name'] and any(has(t) for t in toks(c['name']))]
    return part

def handle_card_answer():
    kind = s('pick_kind')
    said = s('pick_name')
    d = digits(s('card_digits'))
    if s('extra_request') in ('email', 'week'):
        V['pending'] = s('extra_request')
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if kind == 'all_cards':
        retry('Borç bilgisini her seferinde tek bir kart için söyleyebilirim. ' + s('q_select'), q)
        return
    if len(d) >= 4 and (kind == 'digits' or not said):
        handle_digits(cards, d, 'card_q')
        return
    if said:
        m = match_name(said, cards)
        if not m:
            retry('Bu isimde bir kartınız bulunmuyor. Kartlarınız: ' + names_text(cards) + '. ' + q, q)
            return
        nms = set(c['name'] for c in m)
        if len(m) == 1:
            pick(m[0])
            return
        if len(nms) == 1:
            same_name_question(m)
            return
        retry('Kartlarınız: ' + names_text(cards) + '. ' + q, q)
        return
    retry(s('q_select') or q, q)

def handle_digits(pool, d, stage):
    if stage in ('digits4', 'card_q') and len(d) >= 4:
        d4 = d[-4:]
        m = [c for c in pool if c['l4'] == d4]
        if len(d) > 4 and len(m) > 1:
            m2 = [c for c in m if tail_match(c['num'], d) != 'no']
            m = m2 if m2 else m
        if not m:
            retry('Bu son dört haneye sahip bir kartınız bulunmuyor. Kartınızın son dört hanesini söyler misiniz?', 'Kartınızın son dört hanesini söyler misiniz?')
            return
        if len(m) == 1:
            pick(m[0])
            return
        V['cand_json'] = json.dumps([c['num'] for c in m])
        q = 'Son dört hanesi ' + dw(d4) + ' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        ask('ask_digits', 'digits6', q, 'Kartınızın son altı hanesini söyler misiniz?')
        return
    if stage == 'digits6' and len(d) >= 6:
        m = [c for c in pool if tail_match(c['num'], d[-6:]) != 'no']
        if not m:
            retry('Bu son altı haneye sahip bir kartınız bulunmuyor. Kartınızın son altı hanesini söyler misiniz?', 'Kartınızın son altı hanesini söyler misiniz?')
            return
        if len(m) == 1:
            pick(m[0])
            return
        V['cand_json'] = json.dumps([c['num'] for c in m])
        q = 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
        ask('ask_digits', 'digitsfull', q, 'Kart numaranızı söyler misiniz?')
        return
    if stage == 'digitsfull' and len(d) >= 12:
        m = []
        for c in pool:
            n = re.sub(r'[^0-9*]', '', c['num'])
            if len(n) == len(d):
                ok = all(a == '*' or a == b for a, b in zip(n, d))
            else:
                ok = tail_match(c['num'], d) != 'no'
            if ok:
                m.append(c)
        if len(m) == 1:
            pick(m[0])
            return
        retry('Bu numarayla eşleşen tek bir kart bulamadım. Kart numaranızı söyler misiniz?', 'Kart numaranızı söyler misiniz?')
        return
    retry(s('q_full'), s('q_short'))

# ---------------------------------------------------------------------------- reading

def reading(c):
    cur = []
    for cc in ('TL', 'USD', 'EUR', 'GBP'):
        vals = dict()
        for f in ('sd', 'min', 'rem', 'remmin', 'tot', 'auto'):
            vals[f] = fnum('b_' + cc + '_' + f)
        present = any(vals[f] is not None for f in ('sd', 'min', 'rem', 'tot'))
        if present:
            for f in vals:
                if vals[f] is None:
                    vals[f] = 0.0
            cur.append((cc, vals))
    if not cur:
        return None, False
    sdate = pdate(s('bal_sd'))
    lpd = pdate(s('bal_lpd'))
    debt = [(cc, v) for cc, v in cur if v['rem'] > 0]
    if not debt:
        t = cref(c) + 'ınızın ' + (dtr(sdate) + ' tarihli ' if sdate else '') + 'ekstresinden borcunuz bulunmamaktadır.'
        tl = [v for cc, v in cur if cc == 'TL']
        if tl and tl[0]['tot'] > 0:
            t = t + ' Gelecek dönemler dahil toplam borcunuz ' + cop(money(tl[0]['tot'], 'TL')) + '.'
        if lpd and lpd == today:
            t = t + ' Son ödeme tarihiniz bugündür.'
        elif lpd and lpd > today:
            t = t + ' Son ödeme tarihiniz ' + dtr(lpd) + ' olacaktır.'
        return t, False
    lines = []
    for cc, v in debt:
        X = money(v['sd'], cc)
        Y = money(v['rem'], cc)
        Z = money(v['min'], cc)
        if cc == 'TL':
            if v['remmin'] >= v['min']:
                lines.append('Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + cop(Z) + '.')
            elif v['remmin'] <= 0:
                lines.append('Türk Lirası borcunuz ' + X + ', kalan toplam borcunuz ' + cop(Y) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            else:
                T = money(v['remmin'], cc)
                lines.append('Türk Lirası borcunuz ' + X + ', ödenmesi gereken minimum tutar ' + Z + ', kalan toplam borcunuz ' + Y + ', kalan minimum ödeme tutarınız ' + cop(T) + '.')
        else:
            lines.append(CURN[cc] + ' borcunuz ' + X + ', kalan toplam borcunuz ' + Y + ', ödenmesi gereken minimum tutar ' + cop(Z) + '.')
    intro = cref(c) + 'ınıza ait ' + (dtr(sdate) + ' tarihinde kesilen ' if sdate else '') + 'ekstre '
    lines[0] = intro + lines[0]
    nodebt = [CURN[cc] for cc, v in cur if v['rem'] <= 0]
    if nodebt:
        if len(nodebt) == 1:
            nt = nodebt[0]
        else:
            nt = ', '.join(nodebt[:-1]) + ' ve ' + nodebt[-1]
        lines.append(nt + ' borcunuz bulunmamaktadır.')
    for cc, v in cur:
        if v['auto'] > 0:
            lines.append('Kalan otomatik ödeme tutarınız ' + cop(money(v['auto'], cc)) + '.')
    if lpd and lpd == today:
        lines.append('Borçlarınız için son ödeme tarihiniz bugündür.')
    elif lpd:
        lines.append('Borçlarınız için son ödeme tarihiniz ' + dcop(lpd) + '.')
    return ' '.join(lines), True

# ---------------------------------------------------------------------------- offer, e-mail, week

def sel():
    return card_by_num(s('sel_card')) or dict(num=s('sel_card'), l4=s('sel_l4'), name=safe_name(s('sel_name')))

def week_used():
    return s('sel_card') in jload('changed_cards')

def need_email(after, prefix):
    V['after_email'] = after
    V['offer_prefix'] = prefix if prefix.strip() else ' '
    call('email_get', 'email_lookup', ['em_rc', 'em_addr', 'em_tts', 'em_type'])

def offer(prefix=''):
    if s('email_state') in ('', 'unknown'):
        need_email('offer', prefix)
        return
    can_mail = s('email_state') == 'ok' and s('email_sent') != 'yes'
    can_week = not week_used()
    if can_mail and can_week:
        line = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    elif can_week:
        line = 'Hesap kesim tarihinizi değiştirebilirim.'
    elif can_mail:
        line = 'Ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        end('end_main_menu', prefix)
        return
    ask('ask_offer', 'offer', (prefix + ' ' + line).strip(), line)

def email_phrase():
    a = s('em_tts') or s('em_addr')
    local, _, dom = a.partition('@')
    odd = len(local) > 14 or bool(re.search(r'[0-9]', local)) or len(re.findall(r'[._-]', local)) > 1
    if odd and local:
        dn = dom.split('.')[0] if dom else ''
        brand = 'Gmail' if dn.lower() == 'gmail' else dn
        return local[0] + ' ile başlayan ' + (brand + ' ' if brand else '') + 'adresinize'
    return a + ' adresine'

def email_flow(prefix=''):
    if s('email_state') in ('', 'unknown'):
        need_email('email', prefix)
        return
    if s('email_state') == 'error':
        end('end_agent_err')
        return
    if s('email_state') != 'ok':
        line = 'Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
        if not week_used():
            ask('ask_offer', 'offer', (prefix + ' ' + line + ' Hesap kesim tarihinizi değiştirebilirim.').strip(), 'Hesap kesim tarihinizi değiştirebilirim.')
        else:
            end('end_main_menu', (prefix + ' ' + line).strip())
        return
    q = 'Ekstrenizi ' + email_phrase() + ' göndermemi ister misiniz?'
    ask('ask_yn', 'email_confirm', (prefix + ' ' + q).strip(), q)

def week_flow(prefix=''):
    if week_used():
        line = 'Bu kartın hesap kesim tarihi bu yıl zaten değiştirildi. Hesap kesim tarihi yılda yalnızca bir kez değiştirilebiliyor.'
        offer((prefix + ' ' + line).strip())
        return
    V['offer_prefix'] = prefix if prefix.strip() else ' '
    call('week_get', 'week_lookup', ['wk_rc', 'wk_week', 'wk_next_sd', 'wk_next_lpd', 'wk_rel', 'wk_rel_name', 'wk_rel_num'])

def options():
    cur = str(ival(s('wk_week'), 0))
    opts = [w for w in ('1', '2', '3', '4') if w != cur]
    ow = [ORD[w] for w in opts]
    t = ', '.join(ow[:-1]) + ' ya da ' + ow[-1]
    return 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Hesap kesim tarihinizi ayın ' + t + ' haftasına alabilirim. Hangisini tercih edersiniz?', 'Ayın ' + t + ' haftasından hangisini tercih edersiniz?'

def rel_name():
    rel = s('wk_rel').upper()
    if rel not in ('M', 'C'):
        return '', ''
    nm = safe_name(s('wk_rel_name'))
    if not nm:
        l4 = digits(s('wk_rel_num'))[-4:]
        if not l4:
            return '', ''
        nm = 'sonu ' + dw(l4) + ' ile biten'
    return rel, nm

def choose_week(w):
    cur = str(ival(s('wk_week'), 0))
    full, short = options()
    if w not in ('1', '2', '3', '4'):
        retry('Hesap kesim tarihinizi yalnızca bu haftalardan birine alabilirim. ' + full, short)
        return
    if w == cur:
        retry('Kartınızın hesap kesim tarihi zaten her ayın ' + ORD[w] + ' haftası. ' + full, short)
        return
    V['new_week'] = w
    call('week_decide', 'decide', ['dec_rc', 'dec_sd', 'dec_due', 'dec_code'])

def confirm_text():
    w = s('new_week')
    a = pdate(s('dec_sd'))
    b = pdate(s('dec_due'))
    t = 'Yeni hesap kesim haftanız her ayın ' + ORD.get(w, w) + ' haftası olacak. Yeni hesap kesim tarihiniz ' + dtr(a) + ', son ödeme tarihiniz ' + dtr(b) + ' olacak.'
    rel, nm = rel_name()
    if rel:
        t = t + ' Bu değişiklik kartınıza bağlı ' + nm + ' kartınızı da etkileyecek.'
    return t + ' Onaylıyor musunuz?'

def after_action(line):
    can_mail = s('email_state') == 'ok' and s('email_sent') != 'yes'
    can_week = not week_used()
    if can_mail or can_week:
        offer(line)
    else:
        end('end_main_menu', line)

# ---------------------------------------------------------------------------- main

try:
    stage = s('stage')
    V['go_last'] = s('go')
    yn = s('yn')
    oc = s('offer_choice')
    wc = s('week_choice')
    if stage not in ('list', 'balance', 'email_lookup', 'week_lookup', 'decide', 'change', 'send'):
        V['silence_count'] = 0
    if stage == 'list':
        cl = load_cards()
        rc = s('list_rc')
        code = s('list_code')
        V['cards_json'] = json.dumps(cl)
        cards = cl
        if rc == '1' and cl:
            if len(cl) == 1:
                pick(cl[0])
            else:
                select_question(cl)
                V['q_select'] = s('q_full')
        elif (rc == '1' and not cl) or code == 'FB_IVR_CHANNEL_102' or s('cards_list_status_code') == '404':
            end('end_nocard')
        else:
            end('end_agent_err')
    elif stage == 'card_q':
        handle_card_answer()
    elif stage in ('digits4', 'digits6', 'digitsfull'):
        pool = [card_by_num(n) for n in jload('cand_json')]
        pool = [c for c in pool if c]
        d = digits(s('card_digits'))
        if not d:
            retry(s('q_full'), s('q_short'))
        else:
            handle_digits(pool or cards, d, stage)
    elif stage == 'balance':
        c = sel()
        txt, has = (None, False)
        if s('bal_rc') == '1' and not status_bad('balance'):
            txt, has = reading(c)
        if txt is None:
            end('end_agent_err')
        else:
            rd = jload('read_cards')
            if c['num'] not in rd:
                rd.append(c['num'])
            V['read_cards'] = json.dumps(rd)
            V['last_reading'] = txt
            others = [x for x in cards if x['num'] not in rd]
            pend = s('pending')
            V['pending'] = 'none'
            if has and pend == 'email':
                email_flow(txt)
            elif has and pend == 'week':
                week_flow(txt)
            elif others:
                q = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
                ask('ask_yn', 'other_q', txt + ' ' + q, q)
            elif has:
                offer(txt)
            else:
                end('end_main_menu', txt)
    elif stage == 'other_q':
        rd = jload('read_cards')
        others = [x for x in cards if x['num'] not in rd]
        if oc in ('email', 'email_earlier'):
            email_flow('Yalnızca son kesilen ekstrenizi gönderebilirim.' if oc == 'email_earlier' else '')
        elif oc == 'week':
            week_flow('')
        elif yn == 'yes' or oc == 'other_card':
            if len(others) == 1:
                pick(others[0])
            else:
                select_question(others or cards)
                V['q_select'] = s('q_full')
        elif yn == 'no' or oc == 'done':
            offer('')
        else:
            retry(s('q_full'), s('q_short'))
    elif stage == 'offer':
        if oc == 'email':
            email_flow('')
        elif oc == 'email_earlier':
            email_flow('Yalnızca son kesilen ekstrenizi gönderebilirim.')
        elif oc == 'week':
            if wc in ('1', '2', '3', '4'):
                V['pre_week'] = wc
            week_flow('')
        elif oc == 'other_card':
            select_question(cards)
            V['q_select'] = s('q_full')
        elif oc == 'done':
            end('end_main_menu')
        else:
            retry(s('q_full'), s('q_short'))
    elif stage == 'email_lookup':
        rc = s('em_rc')
        addr = s('em_addr') or s('em_tts')
        if rc != '1' or status_bad('email_get'):
            V['email_state'] = 'error'
        elif addr and '@' in addr and s('em_type').lower() != 'phone':
            V['email_state'] = 'ok'
        else:
            V['email_state'] = 'missing'
        pre = s('offer_prefix')
        if s('after_email') == 'email':
            email_flow(pre)
        else:
            offer(pre)
    elif stage == 'email_confirm':
        q = 'Ekstrenizi ' + email_phrase() + ' göndermemi ister misiniz?'
        if yn == 'yes':
            call('pdf_send', 'send', ['snd_rc', 'snd_exit'])
        elif yn == 'no':
            end('end_main_menu')
        elif yn == 'wrong_address':
            end('end_main_menu', 'Kayıtlı e-posta adresinizi bu görüşmede değiştiremiyorum. Adresinizi bankamızın diğer kanallarından güncelleyebilirsiniz.')
        elif yn == 'other_address':
            retry('Ekstrenizi yalnızca bankamızda kayıtlı e-posta adresinize gönderebilirim. ' + q, q)
        elif yn == 'earlier_period':
            retry('Yalnızca son kesilen ekstrenizi gönderebilirim. ' + q, q)
        else:
            retry(q, q)
    elif stage == 'send':
        if s('snd_rc') == '1' and s('snd_exit').upper() == 'DONE' and not status_bad('pdf_send'):
            V['email_sent'] = 'yes'
            after_action('Ekstreniz kayıtlı e-posta adresinize gönderildi.')
        else:
            end('end_agent_err')
    elif stage == 'week_lookup':
        c = sel()
        wk = str(ival(s('wk_week'), 0))
        if s('wk_rc') != '1' or status_bad('week_get') or wk not in ORD:
            end('end_agent_week')
        else:
            rel, nm = rel_name()
            if rel == 'M':
                head = cref(c) + 'ınızın ve buna bağlı ' + nm + ' kartınızın'
            elif rel == 'C':
                head = cref(c) + 'ınızın ve bu kartın bağlı olduğu ' + nm + ' kartınızın'
            else:
                head = cref(c) + 'ınızın'
            t = head + ' hesap kesim tarihi her ayın ' + ORD[wk] + ' haftası olarak tanımlı.'
            a = pdate(s('wk_next_sd'))
            b = pdate(s('wk_next_lpd'))
            if a and b:
                t = t + ' Bir sonraki hesap kesim tarihiniz ' + dtr(a) + ', son ödeme tarihiniz ' + dtr(b) + '.'
            q = 'Hesap kesim tarihinizi değiştirmek ister misiniz?'
            pre = s('offer_prefix')
            ask('ask_yn', 'week_change_q', (pre + ' ' + t + ' ' + q).strip(), q)
    elif stage == 'week_change_q':
        pw = s('pre_week')
        V['pre_week'] = 'none'
        if wc in ('1', '2', '3', '4') and yn != 'no':
            choose_week(wc)
        elif yn == 'yes' and pw in ('1', '2', '3', '4'):
            choose_week(pw)
        elif yn == 'yes':
            full, short = options()
            ask('ask_week', 'week_pick', full, short)
        elif yn == 'no':
            end('end_main_menu')
        else:
            retry(s('q_full'), s('q_short'))
    elif stage == 'week_pick':
        if yn == 'no' and wc not in ('1', '2', '3', '4'):
            end('end_main_menu')
        else:
            choose_week(wc)
    elif stage == 'decide':
        ok = s('dec_rc') == '1' and ival(s('dec_code'), 0) == 0 and pdate(s('dec_sd')) and pdate(s('dec_due')) and not status_bad('week_decide')
        if not ok:
            end('end_agent_week')
        else:
            q = confirm_text()
            ask('ask_yn', 'week_confirm', q, q)
    elif stage == 'week_confirm':
        q = confirm_text()
        if yn == 'yes':
            call('week_change', 'change', ['chg_rc', 'chg_code', 'chg_exit'])
        elif yn == 'no':
            end('end_main_menu')
        else:
            retry('Değişikliği yapabilmem için açık onayınız gerekiyor. ' + q, q)
    elif stage == 'change':
        ok = s('chg_rc') == '1' and ival(s('chg_code'), 0) == 0 and s('chg_exit').upper() in ('OK', '') and not status_bad('week_change')
        if not ok:
            end('end_agent_week')
        else:
            cc = jload('changed_cards')
            cc.append(s('sel_card'))
            V['changed_cards'] = json.dumps(cc)
            c = sel()
            w = s('new_week')
            line = cref(c) + 'ınızın hesap kesim haftası her ayın ' + ORD.get(w, w) + ' haftası olarak değiştirildi. Yeni hesap kesim tarihiniz ' + dtr(pdate(s('dec_sd'))) + ', son ödeme tarihiniz ' + dtr(pdate(s('dec_due'))) + '.'
            after_action(line)
    else:
        end('end_agent_err')
except Exception:
    V['go'] = 'end_agent_err'
    V['done_line'] = ' '
reset_answers()
if not s('q_say'):
    V['q_say'] = 'Sizi dinliyorum.'

